import React, { useState } from "react";
import Inline from "../Inline";
import Radio from "./Radio";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Radio> = {
  id: "Components/Radio",
  title: "Components/Radio Button/Radio Button",
  component: Radio,
  argTypes: {
    icon: {
      table: {
        disable: false,
      },
    },
  },
};

export default meta;
type Story = StoryObj<typeof Radio>;

export const Basic: Story = {
  tags: ["visual-test"],
  args: {
    label: "Label",
    checked: true,
  },
  render: (args) => <Radio {...args} />,
};

export const Disabled: Story = {
  render: () => (
    <Inline spacing="2-x">
      <Radio label="Label" defaultChecked disabled />
      <Radio label="Label" disabled />
    </Inline>
  ),
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  render: () => (
    <Inline spacing="2-x">
      <Radio label="Label" defaultChecked />
      <Radio label="Label" />
    </Inline>
  ),
};

export const Size: Story = {
  render: () => (
    <Inline spacing="2-x">
      <Radio label="Large" defaultChecked size="large" />
      <Radio label="Medium (default)" defaultChecked />
    </Inline>
  ),
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [options, setOptions] = useState({ option1: true, option2: false });
    return (
      <Inline spacing="2-x">
        <Radio
          label="Option 1"
          checked={options.option1}
          onChange={(event) =>
            setOptions({ option1: event.target.checked, option2: false })
          }
        />
        <Radio
          label="Option 2"
          checked={options.option2}
          onChange={(event) =>
            setOptions({ option1: false, option2: event.target.checked })
          }
        />
      </Inline>
    );
  },
};
